begin; do $$ declare r jsonb; d jsonb; j jsonb; claimed jsonb; rid uuid:=gen_random_uuid(); bot bigint:=900000001; usr bigint:=900000002; admin bigint:=900000003; begin update public.bot_control set bot_id=bot,owner_id=admin where id='local'; update public.worker_state set ready=true,last_seen=now(); r:=public.request_access(bot,usr,'Тест','Проверка','test_guest','politics','Дипломатия',rid,'miniapp'); if r->>'status'<>'pending' then raise exception 'pending failed';end if; d:=public.request_access(bot,usr,'Тест','Проверка','test_guest','ai','',gen_random_uuid(),'chat'); if d->>'id'<>r->>'id' then raise exception 'duplicate pending';end if; update public.access_requests set owner_message_id=80 where id=(r->>'id')::uuid; if public.decide_access((r->>'id')::uuid,usr,80,true) is not null then raise exception 'foreign decision accepted';end if; if public.decide_access((r->>'id')::uuid,admin,81,true) is not null then raise exception 'wrong message accepted';end if; d:=public.decide_access((r->>'id')::uuid,admin,80,true); if d->>'status'<>'approved' or not exists(select 1 from public.bot_members where bot_id=bot and user_id=usr) then raise exception 'approval failed';end if; if public.decide_access((r->>'id')::uuid,admin,80,true) is not null then raise exception 'duplicate approval';end if; j:=public.begin_news_job(usr,'politics','Дипломатия',rid); update public.jobs set bot_id=bot where id=(j->'job'->>'id')::uuid; claimed:=public.worker_claim(admin); if claimed is null or claimed->>'id'<>j->'job'->>'id' then raise exception 'guest queue claim failed';end if; if public.worker_claim(admin) is not null then raise exception 'parallel claim';end if; if public.worker_finish(admin,(claimed->>'id')::uuid,gen_random_uuid(),null,'test') then raise exception 'wrong lease';end if; if not public.worker_finish(admin,(claimed->>'id')::uuid,(claimed->>'lease')::uuid,null,'test') then raise exception 'guest finish failed';end if; r:=public.request_access(bot,usr+1,'Отказ','','','weather','',gen_random_uuid(),'chat'); update public.access_requests set owner_message_id=81 where id=(r->>'id')::uuid; d:=public.decide_access((r->>'id')::uuid,admin,81,false); if d->>'status'<>'denied' or exists(select 1 from public.bot_members where bot_id=bot and user_id=usr+1) then raise exception 'denial failed';end if; d:=public.request_access(bot,usr+1,'Отказ','','','weather','',gen_random_uuid(),'chat'); if d->>'status'<>'denied' then raise exception 'cooldown failed';end if; end $$; rollback;
